                    data <= fib_reg;
                    counter <= 0;
                end
                else begin
                    temp_reg <= fib_reg;
                    fib_reg <= next_val;
                    next_val <= fib_reg + temp_reg;
                    counter <= counter + 1;
                end
            end
        end
    end
